}
}

// === EXAM 2023-2024 Session 1 — Ex.2 Classe Produit (3 pts) ===
<?php
class Produit {
    private $nom;
    private $categorie;
    private $prix;

    public function __construct($nom, $categorie, $prix) {
        $this->nom = $nom;
        $this->categorie = $categorie;
        $this->prix = $prix;
    }

    public function afficherProduit() {
        echo "Le produit {$this->nom} appartient a la categorie {$this->categorie} et coute {$this->prix} euros.";
    }
}

$produit = new Produit("Televiseur 4K", "Electronique", 799);
$produit->afficherProduit();
?>
